#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
struct Item{uint64_t key;uint32_t f32,q8,input,pad;};static_assert(sizeof(Item)==24);struct Key{uint64_t bits;uint32_t target,input;};int main(){FILE*f=fopen("native-mixed-q8-image.bin","rb");if(!f)return 3;std::vector<Item>v(54675);if(fread(v.data(),24,v.size(),f)!=v.size())return 3;fclose(f);for(int drop=0;drop<=23;drop++){uint64_t mask=(uint64_t(uint32_t(0xffffffffU<<drop))<<16)|65535;std::vector<Key>k;for(Item e:v)k.push_back({e.key&mask,e.q8,e.input});std::sort(k.begin(),k.end(),[](Key a,Key b){return a.bits<b.bits||(a.bits==b.bits&&a.target<b.target);});int states=0,collisions=0;Key a{},b{};for(int i=0;i<(int)k.size();i++)if(!i||k[i].bits!=k[i-1].bits)states++;else if(k[i].target!=k[i-1].target){if(!collisions){a=k[i-1];b=k[i];}collisions++;}printf("{\"drop_mantissa_bits\":%d,\"mask\":%llu,\"states\":%d,\"collisions\":%d,\"witness\":{\"key\":%llu,\"targets\":[%u,%u],\"inputs\":[%u,%u]}}\n",drop,(unsigned long long)mask,states,collisions,(unsigned long long)a.bits,a.target,b.target,a.input,b.input);if(!collisions){std::vector<Key>image;for(Key e:k)if(image.empty()||image.back().bits!=e.bits)image.push_back(e);char name[80];sprintf(name,"q8-prefix-drop%d.bin",drop);FILE*g=fopen(name,"wb");if(!g||fwrite(image.data(),16,image.size(),g)!=image.size())return 4;fclose(g);}}}
